import { DropZone as AriaDropZone } from "react-aria-components";
import type { DropZoneProps as AriaDropZoneProps } from "react-aria-components";
import type { ReactNode, Ref } from "react";
import "./DropZone.css";

export interface DropZoneProps
  extends Omit<AriaDropZoneProps, "className" | "children"> {
  /** Drop zone content. */
  children?: ReactNode;
  /** Additional class. sd-drop-zone is always retained. */
  className?: string;
  /** Passed to the root drop zone DOM element. */
  ref?: Ref<HTMLDivElement>;
}

export function DropZone({ children, className, ref, ...props }: DropZoneProps) {
  return (
    <AriaDropZone
      {...props}
      ref={ref}
      className={className ? `sd-drop-zone ${className}` : "sd-drop-zone"}
    >
      {children}
    </AriaDropZone>
  );
}

.sd-drop-zone {
  display: flex;
  /* A zone stacks its parts: `text-align: center` and `min-height` beside it assume a column, and
     without the direction several children fall into a `row` (`DropZone/MultiPart` renders it). */
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: var(--sd-drop-zone-gap);
  min-height: var(--sd-drop-zone-min-height);
  padding: var(--sd-drop-zone-padding);
  color: var(--sd-drop-zone-foreground);
  background: var(--sd-drop-zone-background);
  border: var(--sd-drop-zone-border-width) var(--sd-drop-zone-border-style) var(--sd-drop-zone-border);
  border-radius: var(--sd-drop-zone-radius);
  corner-shape: superellipse(var(--sd-radius-curve));
  text-align: center;
  transition:
    background-color var(--sd-duration-moderate) var(--sd-easing-standard),
    color var(--sd-duration-moderate) var(--sd-easing-standard),
    border-color var(--sd-duration-moderate) var(--sd-easing-standard);
  outline: none;
}

.sd-drop-zone[data-drop-target] {
  background: var(--sd-drop-zone-background-drop-target);
  color: var(--sd-drop-zone-foreground-drop-target);
  border-color: var(--sd-drop-zone-border-drop-target);
  border-style: var(--sd-drop-zone-border-style-drop-target);
}

.sd-drop-zone[data-focus-visible] {
  box-shadow: 0 0 0 var(--sd-state-focus-ring-width) color-mix(in srgb, var(--sd-state-focus-ring) calc(var(--sd-state-focus-ring-opacity) * 100%), transparent);
  outline: var(--sd-state-focus-ring-width) solid transparent;
}

.sd-drop-zone[data-disabled] {
  opacity: var(--sd-state-disabled);
}
